177	    ['REQUEST_CHANGES', 'Request changes'],
178	    ['COMMENT', 'Comment'],
179	    ['NONE', "Don't post"]
180	  ];
181	  const TABS = [
182	    ['needs', 'Needs you'],
183	    ['queued', 'Queued'],
184	    ['hold', 'On hold'],
185	    ['done', 'Done'],
186	    ['all', 'All']
187	  ];
188	
189	  const state = { prs: new Map(), decisions: new Map(), local: new Map(), filter: 'needs', db: null, canWrite: true, loaded: { prs: false, decisions: false } };
190	  try { const f = localStorage.getItem('prdesk.filter'); if (f && TABS.some(t => t[0] === f)) state.filter = f; } catch (e) {}
191	
192	  const $ = (id) => document.getElementById(id);
