196	
197	  function bucket(pr) {
198	    const d = state.decisions.get(String(pr.number));
199	    if (d && d.status === 'done') return 'done';
200	    if (pr.verdict === 'merged' || pr.verdict === 'closed') return 'done';
201	    if (d && d.status === 'queued') return 'queued';
202	    if (d && d.status === 'hold') return 'hold';
203	    return 'needs';
204	  }
205	
206	  // The working copy of a decision: unsaved local edits, else the stored decision, else Claude's draft.
207	  function working(pr) {
208	    const key = String(pr.number);
209	    const stored = state.decisions.get(key) || {};
210	    const local = state.local.get(key) || {};
211	    const fixIds = (pr.fixes || []).map(f => f.id);
212	    return {
213	      comment: local.comment ?? stored.comment ?? pr.comment ?? '',
214	      event: local.event ?? stored.event ?? pr.event ?? 'COMMENT',
215	      fixes: local.fixes ?? stored.fixes ?? fixIds.filter(id => (pr.fixes.find(f => f.id === id) || {}).preselect),
216	      merge: local.merge ?? stored.merge ?? false,
217	      status: stored.status || null,
218	      decidedAt: stored.decidedAt || null
219	    };
220	  }
221	
222	  function renderTabs() {
223	    const counts = { needs: 0, queued: 0, hold: 0, done: 0, all: state.prs.size };
224	    state.prs.forEach(pr => { counts[bucket(pr)]++; });
225	    $('tabs').innerHTML = TABS.map(([k, label]) =>
226	      `<button class="tab" role="tab" data-tab="${k}" aria-selected="${state.filter === k}">${label}<span class="n">${counts[k]}</span></button>`).join('');
227	    $('queuedNote').textContent = counts.queued ? `· ${counts.queued} queued` : '';
228	  }
