230	  function cardHtml(pr) {
231	    const key = String(pr.number);
232	    const w = working(pr);
233	    const v = VERDICTS[pr.verdict] || { label: pr.verdict || 'Unreviewed', cls: '' };
234	    const mergeCls = { mergeable: 'ok', conflicting: 'bad', behind: 'warn', blocked: 'warn' }[pr.merge] || '';
235	    const ciCls = { passing: 'ok', failing: 'bad', pending: 'warn' }[pr.ci] || '';
236	    const locked = !state.canWrite || w.status === 'queued' || w.status === 'done';
237	    const findings = pr.findings || [];
238	    const fixes = pr.fixes || [];
239	    const d = state.decisions.get(key) || {};
240	
241	    let status = '';
242	    if (w.status === 'queued') status = `<span class="status queued">Queued ${esc(fmtTime(w.decidedAt))} · Claude acts on it next</span>`;
243	    else if (w.status === 'hold') status = `<span class="status">On hold</span>`;
244	    else if (w.status === 'draft') status = `<span class="status">Draft saved</span>`;
245	    else if (w.status === 'done') status = `<span class="status">Done ${esc(fmtTime(d.doneAt))}</span>`;
246	
247	    const staleSha = d.prSha && pr.headSha && d.prSha !== pr.headSha && w.status !== 'done';
248	
249	    return `<article class="card" data-verdict="${esc(pr.verdict)}" data-pr="${key}">
250	      <div class="card-head">
251	        <div class="card-title"><a class="num" href="${esc(pr.url)}" target="_blank" rel="noopener">#${key}</a><h2>${esc(pr.title)}</h2></div>
252	        <div class="meta">
253	          <span class="pill verdict ${v.cls}">${esc(v.label)}</span>
254	          ${pr.merge ? `<span class="pill ${mergeCls}">${esc(pr.merge)}</span>` : ''}
255	          ${pr.ci ? `<span class="pill ${ciCls}">CI ${esc(pr.ci)}</span>` : ''}
256	          <span>by ${esc(pr.author)}</span>
257	          ${pr.size ? `<span class="mono">${esc(pr.size)}</span>` : ''}
258	          ${pr.headSha ? `<span class="sha" title="Commit reviewed">@${esc(String(pr.headSha).slice(0, 7))}</span>` : ''}
259	          ${pr.reviewedAt ? `<span>reviewed ${esc(fmtTime(pr.reviewedAt))}</span>` : ''}
260	        </div>
261	      </div>
262	      ${pr.summary ? `<p class="summary">${inline(pr.summary)}</p>` : ''}
263	      ${pr.question ? `<div class="question"><b>Your call:</b> ${inline(pr.question)}</div>` : ''}
264	      ${pr.ciNote ? `<p class="summary"><b>CI:</b> ${inline(pr.ciNote)}</p>` : ''}
265	      ${pr.outcome ? `<div class="outcome">${inline(pr.outcome)}</div>` : ''}
266	      ${staleSha ? `<div class="question"><b>New commits:</b> the PR changed after you decided. Claude will re-check before acting.</div>` : ''}
267	      ${findings.length ? `<details class="findings"${findings.length <= 4 ? ' open' : ''}><summary>Findings (${findings.length})</summary><ol>${findings.map(f =>
268	        `<li><span class="sev ${esc(f.sev)}">${esc(f.sev)}</span><span>${inline(f.text)}${f.where ? `<span class="where">${esc(f.where)}</span>` : ''}</span></li>`).join('')}</ol></details>` : ''}
269	      ${fixes.length ? `<div class="compose"><div class="block-label">We fix on the branch ourselves</div><div class="fixes">${fixes.map(f =>
270	        `<label class="fix"><input type="checkbox" id="fix-${key}-${esc(f.id)}" data-act="fix" data-fix="${esc(f.id)}"${w.fixes.includes(f.id) ? ' checked' : ''}${locked ? ' disabled' : ''}><span>${inline(f.text)}</span></label>`).join('')}</div></div>` : ''}
271	      <div class="compose">
272	        <div class="block-label"><label for="c-${key}">Comment to ${esc(pr.author)}</label>${!locked && (state.local.has(key) || d.comment) && pr.comment ? `<button class="btn link" data-act="reset">Use Claude's draft</button>` : ''}</div>
273	        <textarea id="c-${key}" data-act="comment"${locked ? ' disabled' : ''}>${esc(w.comment)}</textarea>
274	        <div class="controls">
275	          <span class="seg" role="group" aria-label="Review type">${EVENTS.map(([k, label]) =>
276	            `<button type="button" data-act="event" data-event="${k}" aria-pressed="${w.event === k}"${locked ? ' disabled' : ''}>${label}</button>`).join('')}</span>
277	          ${w.event === 'APPROVE' ? `<label class="check"><input type="checkbox" id="m-${key}" data-act="merge"${w.merge ? ' checked' : ''}${locked ? ' disabled' : ''}>Merge once CI passes</label>` : ''}
278	        </div>
279	      </div>
280	      <div class="actions">
281	        ${w.status === 'queued' || w.status === 'hold'
282	          ? `<button class="btn" data-act="edit"${!state.canWrite ? ' disabled' : ''}>Back to editing</button>`
283	          : w.status === 'done' ? '' :
284	          `<button class="btn primary" data-act="queue"${!state.canWrite ? ' disabled' : ''}>Queue for Claude</button>
285	           <button class="btn" data-act="hold"${!state.canWrite ? ' disabled' : ''}>Hold</button>`}
286	        ${status}
287	      </div>
288	    </article>`;
289	  }
290	
291	  function render() {
292	    renderTabs();
293	    const list = $('list');
294	    const active = document.activeElement;
295	    const activeId = active && active.id;
296	    const sel = active && 'selectionStart' in active ? [active.selectionStart, active.selectionEnd] : null;
297	
298	    const prs = [...state.prs.values()]
299	      .filter(pr => state.filter === 'all' || bucket(pr) === state.filter)
300	      .sort((a, b) => (a.order ?? 999) - (b.order ?? 999) || a.number - b.number);
301	
302	    const notice = $('notice');
303	    if (!state.loaded.prs) { notice.hidden = false; }
304	    else if (state.prs.size === 0) { notice.hidden = false; notice.textContent = 'No pull requests yet. Ask Claude to "review the new PRs" and they appear here.'; }
305	    else if (prs.length === 0) { notice.hidden = false; notice.textContent = { needs: 'Nothing needs you. Queued items wait for Claude.', queued: 'Nothing queued.', hold: 'Nothing on hold.', done: 'Nothing done yet.' }[state.filter] || 'Nothing here.'; }
306	    else notice.hidden = true;
307	
308	    list.innerHTML = prs.map(cardHtml).join('');
309	    if (activeId) {
310	      const el = document.getElementById(activeId);
311	      if (el) { el.focus(); if (sel && 'setSelectionRange' in el) { try { el.setSelectionRange(sel[0], sel[1]); } catch (e) {} } }
312	    }
313	  }
314	
315	  // Saving: drafts are written on a pause in typing; queue/hold write immediately.
316	  const timers = new Map();
317	  const writing = new Map();
318	  async function save(key, extra) {
319	    if (!state.db) return;
320	    const pr = state.prs.get(key); if (!pr) return;
321	    const w = working(pr);
322	    const body = {
323	      number: pr.number, comment: w.comment, event: w.event, fixes: w.fixes, merge: w.event === 'APPROVE' && w.merge,
324	      status: w.status && w.status !== 'done' ? w.status : 'draft', prSha: pr.headSha || null, decidedAt: new Date().toISOString(),
325	      ...extra
326	    };
327	    // One write at a time per document.
328	    const prev = writing.get(key) || Promise.resolve();
329	    const next = prev.then(() => state.db.doc('decisions/' + key).set(body)).then(() => {
330	      state.local.delete(key);
331	    }).catch(err => {
332	      if (err && err.code === 'invalid_argument') { state.canWrite = false; render(); }
333	      showError(err);
334	    });
335	    writing.set(key, next);
336	    return next;
337	  }
338	  function saveSoon(key) {
339	    clearTimeout(timers.get(key));
340	    timers.set(key, setTimeout(() => save(key), 900));
341	  }
342	  function setLocal(key, patch) {
343	    const pr = state.prs.get(key); const w = working(pr);
344	    state.local.set(key, { comment: w.comment, event: w.event, fixes: w.fixes, merge: w.merge, ...(state.local.get(key) || {}), ...patch });
345	  }
