351	  }
352	
353	  document.addEventListener('click', (e) => {
354	    const tab = e.target.closest('[data-tab]');
355	    if (tab) { state.filter = tab.dataset.tab; try { localStorage.setItem('prdesk.filter', state.filter); } catch (err) {} render(); return; }
356	    const btn = e.target.closest('button[data-act]');
357	    if (!btn) return;
358	    const card = btn.closest('[data-pr]'); if (!card) return;
359	    const key = card.dataset.pr;
360	    const act = btn.dataset.act;
361	    if (act === 'event') { setLocal(key, { event: btn.dataset.event }); render(); saveSoon(key); }
362	    else if (act === 'reset') { const pr = state.prs.get(key); setLocal(key, { comment: pr.comment || '' }); render(); saveSoon(key); }
363	    else if (act === 'queue') { clearTimeout(timers.get(key)); save(key, { status: 'queued' }); }
364	    else if (act === 'hold') { clearTimeout(timers.get(key)); save(key, { status: 'hold' }); }
