366	  });
367	  document.addEventListener('input', (e) => {
368	    const el = e.target; const card = el.closest && el.closest('[data-pr]'); if (!card) return;
369	    const key = card.dataset.pr;
370	    if (el.dataset.act === 'comment') { setLocal(key, { comment: el.value }); saveSoon(key); }
371	  });
