373	    const el = e.target; const card = el.closest && el.closest('[data-pr]'); if (!card) return;
374	    const key = card.dataset.pr;
375	    if (el.dataset.act === 'fix') {
376	      const ids = [...card.querySelectorAll('input[data-act="fix"]:checked')].map(i => i.dataset.fix);
377	      setLocal(key, { fixes: ids }); saveSoon(key);
378	    } else if (el.dataset.act === 'merge') { setLocal(key, { merge: el.checked }); saveSoon(key); }
379	  });
380	
381	  render();
382	
383	  (async function start() {
384	    const db = await window.claude?.use?.('db');
385	    if (!db) { $('notice').textContent = 'Open this page in Claude to see and decide on pull requests.'; return; }
386	    state.db = db;
387	    const user = await window.claude.use('user');
388	    if (user) { try { const c = await user.can('data.write'); if (c === false) state.canWrite = false; } catch (e) {} }
389	
390	    const slow = setTimeout(() => { if (!state.loaded.prs) $('notice').textContent = "The desk can't be reached yet. It will fill in when the connection returns."; }, 10000);
