392	      state.prs = new Map(snap.docs.map(d => [d.id, d.data()]));
393	      if (!snap.metadata.fromCache) { state.loaded.prs = true; clearTimeout(slow); }
394	      else if (snap.size) state.loaded.prs = true;
395	      const latest = [...state.prs.values()].map(p => p.reviewedAt).filter(Boolean).sort().pop();
396	      $('reviewed').textContent = latest ? 'last review ' + fmtTime(latest) : 'no reviews yet';
397	      render();
398	    }, () => { clearTimeout(slow); state.loaded.prs = true; $('notice').textContent = 'The desk could not load. Reopen the page to try again.'; });
