.sev { font-family: var(--font-mono); font-size: 11px; text-transform: uppercase; padding-top: 3px; }
.sev.high { color: var(--bad); } .sev.medium { color: var(--warn); } .sev.low, .sev.nit { color: var(--muted); }
.where { display: block; font-family: var(--font-mono); font-size: 12px; color: var(--muted); overflow-wrap: anywhere; }

.block-label { font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.06em; color: var(--muted); display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }
.block-label button { text-transform: none; letter-spacing: 0; font-weight: 400; }
.fixes { display: flex; flex-direction: column; gap: 6px; }
.fix { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px; align-items: start; font-size: 14px; cursor: pointer; }
.fix input { margin-top: 4px; accent-color: var(--accent); }
textarea { width: 100%; min-height: 160px; resize: vertical; border: 1px solid var(--line); border-radius: 6px; background: var(--bg); padding: 10px 12px; font-family: var(--font-mono); font-size: 13px; line-height: 1.55; }
textarea:disabled { opacity: .75; }
.compose { display: flex; flex-direction: column; gap: 8px; }
.controls { display: flex; flex-wrap: wrap; gap: 8px 14px; align-items: center; font-size: 14px; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 6px; overflow: hidden; flex-wrap: wrap; }
.seg button { background: none; border: 0; padding: 5px 11px; cursor: pointer; font-size: 13px; color: var(--muted); transition: background-color .15s, color .15s; }
.seg button + button { border-left: 1px solid var(--line); }
.seg button[aria-pressed="true"] { background: var(--ink); color: var(--surface); }
.check { display: inline-flex; gap: 6px; align-items: center; cursor: pointer; }
.check input { accent-color: var(--accent); }
.actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; border-top: 1px solid var(--line); padding-top: 12px; }
.btn { border-radius: 6px; padding: 7px 14px; cursor: pointer; font-size: 14px; font-weight: 500; border: 1px solid var(--line); background: var(--surface); transition: background-color .15s; }
.btn:hover { background: var(--bg); }
.btn.primary { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.btn.primary:hover { filter: brightness(1.08); background: var(--accent); }
.btn.link { border: 0; background: none; color: var(--accent); padding: 0; font-weight: 400; font-size: 13px; }
.btn:disabled { opacity: .5; cursor: default; }
.status { font-size: 13px; color: var(--muted); margin-left: auto; }
.status.queued { color: var(--accent); font-weight: 500; }
.outcome { font-size: 14px; background: var(--ok-bg); border-radius: 6px; padding: 8px 12px; }
.sha { font-family: var(--font-mono); font-size: 12px; }
footer { font-size: 12px; color: var(--muted); }

@media (max-width: 560px) {
  .steps { grid-template-columns: 1fr; }
  details.findings li { grid-template-columns: 1fr; gap: 0; }
  .status { margin-left: 0; width: 100%; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
</style>

<div class="wrap">
  <header class="top">
    <div class="top-row">
      <h1>Maester PR Desk</h1>
      <span class="repo">maester365/maester · <span id="reviewed">waiting for reviews</span></span>
    </div>
    <ol class="steps">
      <li><b>1 · Claude reviews</b>Each open PR gets a verdict, findings and a draft comment.</li>
      <li class="now"><b>2 · You decide</b>Edit the comment, pick fixes we make ourselves, then queue it.</li>
      <li><b>3 · Claude acts</b>Posts the review, pushes fixes, merges, and logs the outcome here.</li>
    </ol>
    <div class="process">When you're done, tell Claude <kbd>process the PR desk</kbd><span id="queuedNote"></span></div>
  </header>

  <nav class="tabs" role="tablist" aria-label="Filter pull requests" id="tabs"></nav>

  <div id="notice" class="notice">Loading pull requests…</div>
  <div class="list" id="list"></div>

  <footer>Only you and editors can change decisions. Claude reads queued decisions when you ask it to process the desk; nothing is posted from this page directly.</footer>
</div>

<script>
(function () {
  const VERDICTS = {
    ready:      { label: 'Ready to merge',      cls: 'ok' },
    'small-fix':{ label: 'Merge after small fix', cls: 'warn' },
    changes:    { label: 'Request changes',     cls: 'bad' },
    decision:   { label: 'Needs your call',     cls: 'ask' },
    merged:     { label: 'Merged',              cls: 'ok' },
    closed:     { label: 'Closed',              cls: '' }
  };
  const EVENTS = [
    ['APPROVE', 'Approve'],
    ['REQUEST_CHANGES', 'Request changes'],
    ['COMMENT', 'Comment'],
    ['NONE', "Don't post"]
  ];
  const TABS = [
    ['needs', 'Needs you'],
    ['queued', 'Queued'],
    ['hold', 'On hold'],
    ['done', 'Done'],
    ['all', 'All']
  ];

  const state = { prs: new Map(), decisions: new Map(), local: new Map(), filter: 'needs', db: null, canWrite: true, loaded: { prs: false, decisions: false } };
  try { const f = localStorage.getItem('prdesk.filter'); if (f && TABS.some(t => t[0] === f)) state.filter = f; } catch (e) {}

  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const inline = (s) => esc(s).replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>');
  const fmtTime = (iso) => { if (!iso) return ''; const d = new Date(iso); return isNaN(d) ? '' : d.toLocaleString(undefined, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }); };

  function bucket(pr) {
    const d = state.decisions.get(String(pr.number));
    if (d && d.status === 'done') return 'done';
    if (pr.verdict === 'merged' || pr.verdict === 'closed') return 'done';
    if (d && d.status === 'queued') return 'queued';
    if (d && d.status === 'hold') return 'hold';
    return 'needs';
  }

  // The working copy of a decision: unsaved local edits, else the stored decision, else Claude's draft.
  function working(pr) {
    const key = String(pr.number);
    const stored = state.decisions.get(key) || {};
    const local = state.local.get(key) || {};
    const fixIds = (pr.fixes || []).map(f => f.id);
    return {
      comment: local.comment ?? stored.comment ?? pr.comment ?? '',
      event: local.event ?? stored.event ?? pr.event ?? 'COMMENT',
      fixes: local.fixes ?? stored.fixes ?? fixIds.filter(id => (pr.fixes.find(f => f.id === id) || {}).preselect),
      merge: local.merge ?? stored.merge ?? false,
      status: stored.status || null,
      decidedAt: stored.decidedAt || null
    };
  }

  function renderTabs() {
    const counts = { needs: 0, queued: 0, hold: 0, done: 0, all: state.prs.size };
    state.prs.forEach(pr => { counts[bucket(pr)]++; });
    $('tabs').innerHTML = TABS.map(([k, label]) =>
      `<button class="tab" role="tab" data-tab="${k}" aria-selected="${state.filter === k}">${label}<span class="n">${counts[k]}</span></button>`).join('');
    $('queuedNote').textContent = counts.queued ? `· ${counts.queued} queued` : '';
  }

  function cardHtml(pr) {
    const key = String(pr.number);
    const w = working(pr);
    const v = VERDICTS[pr.verdict] || { label: pr.verdict || 'Unreviewed', cls: '' };
    const mergeCls = { mergeable: 'ok', conflicting: 'bad', behind: 'warn', blocked: 'warn' }[pr.merge] || '';
    const ciCls = { passing: 'ok', failing: 'bad', pending: 'warn' }[pr.ci] || '';
    const locked = !state.canWrite || w.status === 'queued' || w.status === 'done';
    const findings = pr.findings || [];
    const fixes = pr.fixes || [];
    const d = state.decisions.get(key) || {};

    let status = '';
    if (w.status === 'queued') status = `<span class="status queued">Queued ${esc(fmtTime(w.decidedAt))} · Claude acts on it next</span>`;
    else if (w.status === 'hold') status = `<span class="status">On hold</span>`;
    else if (w.status === 'draft') status = `<span class="status">Draft saved</span>`;
    else if (w.status === 'done') status = `<span class="status">Done ${esc(fmtTime(d.doneAt))}</span>`;

    const staleSha = d.prSha && pr.headSha && d.prSha !== pr.headSha && w.status !== 'done';

    return `<article class="card" data-verdict="${esc(pr.verdict)}" data-pr="${key}">
      <div class="card-head">
        <div class="card-title"><a class="num" href="${esc(pr.url)}" target="_blank" rel="noopener">#${key}</a><h2>${esc(pr.title)}</h2></div>
        <div class="meta">
          <span class="pill verdict ${v.cls}">${esc(v.label)}</span>
          ${pr.merge ? `<span class="pill ${mergeCls}">${esc(pr.merge)}</span>` : ''}
          ${pr.ci ? `<span class="pill ${ciCls}">CI ${esc(pr.ci)}</span>` : ''}
          <span>by ${esc(pr.author)}</span>
          ${pr.size ? `<span class="mono">${esc(pr.size)}</span>` : ''}
          ${pr.headSha ? `<span class="sha" title="Commit reviewed">@${esc(String(pr.headSha).slice(0, 7))}</span>` : ''}
          ${pr.reviewedAt ? `<span>reviewed ${esc(fmtTime(pr.reviewedAt))}</span>` : ''}
        </div>
      </div>
      ${pr.summary ? `<p class="summary">${inline(pr.summary)}</p>` : ''}
      ${pr.question ? `<div class="question"><b>Your call:</b> ${inline(pr.question)}</div>` : ''}
      ${pr.ciNote ? `<p class="summary"><b>CI:</b> ${inline(pr.ciNote)}</p>` : ''}
      ${pr.outcome ? `<div class="outcome">${inline(pr.outcome)}</div>` : ''}
      ${staleSha ? `<div class="question"><b>New commits:</b> the PR changed after you decided. Claude will re-check before acting.</div>` : ''}
      ${findings.length ? `<details class="findings"${findings.length <= 4 ? ' open' : ''}><summary>Findings (${findings.length})</summary><ol>${findings.map(f =>
        `<li><span class="sev ${esc(f.sev)}">${esc(f.sev)}</span><span>${inline(f.text)}${f.where ? `<span class="where">${esc(f.where)}</span>` : ''}</span></li>`).join('')}</ol></details>` : ''}
      ${fixes.length ? `<div class="compose"><div class="block-label">We fix on the branch ourselves</div><div class="fixes">${fixes.map(f =>
        `<label class="fix"><input type="checkbox" id="fix-${key}-${esc(f.id)}" data-act="fix" data-fix="${esc(f.id)}"${w.fixes.includes(f.id) ? ' checked' : ''}${locked ? ' disabled' : ''}><span>${inline(f.text)}</span></label>`).join('')}</div></div>` : ''}
      <div class="compose">
        <div class="block-label"><label for="c-${key}">Comment to ${esc(pr.author)}</label>${!locked && (state.local.has(key) || d.comment) && pr.comment ? `<button class="btn link" data-act="reset">Use Claude's draft</button>` : ''}</div>
        <textarea id="c-${key}" data-act="comment"${locked ? ' disabled' : ''}>${esc(w.comment)}</textarea>
        <div class="controls">
          <span class="seg" role="group" aria-label="Review type">${EVENTS.map(([k, label]) =>
            `<button type="button" data-act="event" data-event="${k}" aria-pressed="${w.event === k}"${locked ? ' disabled' : ''}>${label}</button>`).join('')}</span>
          ${w.event === 'APPROVE' ? `<label class="check"><input type="checkbox" id="m-${key}" data-act="merge"${w.merge ? ' checked' : ''}${locked ? ' disabled' : ''}>Merge once CI passes</label>` : ''}
        </div>
      </div>
      <div class="actions">
        ${w.status === 'queued' || w.status === 'hold'
          ? `<button class="btn" data-act="edit"${!state.canWrite ? ' disabled' : ''}>Back to editing</button>`
          : w.status === 'done' ? '' :
          `<button class="btn primary" data-act="queue"${!state.canWrite ? ' disabled' : ''}>Queue for Claude</button>
           <button class="btn" data-act="hold"${!state.canWrite ? ' disabled' : ''}>Hold</button>`}
        ${status}
      </div>
    </article>`;
  }

  function render() {
    renderTabs();
    const list = $('list');
    const active = document.activeElement;
    const activeId = active && active.id;
    const sel = active && 'selectionStart' in active ? [active.selectionStart, active.selectionEnd] : null;

    const prs = [...state.prs.values()]
      .filter(pr => state.filter === 'all' || bucket(pr) === state.filter)
      .sort((a, b) => (a.order ?? 999) - (b.order ?? 999) || a.number - b.number);

    const notice = $('notice');
    if (!state.loaded.prs) { notice.hidden = false; }
    else if (state.prs.size === 0) { notice.hidden = false; notice.textContent = 'No pull requests yet. Ask Claude to "review the new PRs" and they appear here.'; }
    else if (prs.length === 0) { notice.hidden = false; notice.textContent = { needs: 'Nothing needs you. Queued items wait for Claude.', queued: 'Nothing queued.', hold: 'Nothing on hold.', done: 'Nothing done yet.' }[state.filter] || 'Nothing here.'; }
    else notice.hidden = true;

    list.innerHTML = prs.map(cardHtml).join('');
    if (activeId) {
      const el = document.getElementById(activeId);
      if (el) { el.focus(); if (sel && 'setSelectionRange' in el) { try { el.setSelectionRange(sel[0], sel[1]); } catch (e) {} } }
    }
  }

  // Saving: drafts are written on a pause in typing; queue/hold write immediately.
  const timers = new Map();
  const writing = new Map();
  async function save(key, extra) {
    if (!state.db) return;
    const pr = state.prs.get(key); if (!pr) return;
    const w = working(pr);
    const body = {
      number: pr.number, comment: w.comment, event: w.event, fixes: w.fixes, merge: w.event === 'APPROVE' && w.merge,
      status: w.status && w.status !== 'done' ? w.status : 'draft', prSha: pr.headSha || null, decidedAt: new Date().toISOString(),
      ...extra
    };
    // One write at a time per document.
    const prev = writing.get(key) || Promise.resolve();
    const next = prev.then(() => state.db.doc('decisions/' + key).set(body)).then(() => {
      state.local.delete(key);
    }).catch(err => {
      if (err && err.code === 'invalid_argument') { state.canWrite = false; render(); }
      showError(err);
    });
    writing.set(key, next);
    return next;
  }
  function saveSoon(key) {
    clearTimeout(timers.get(key));
    timers.set(key, setTimeout(() => save(key), 900));
  }
  function setLocal(key, patch) {
    const pr = state.prs.get(key); const w = working(pr);
    state.local.set(key, { comment: w.comment, event: w.event, fixes: w.fixes, merge: w.merge, ...(state.local.get(key) || {}), ...patch });
  }
  function showError(err) {
    const n = $('notice');
    n.hidden = false;
    n.textContent = err && err.code === 'quota_exceeded' ? 'The desk is full. Ask Claude to clear finished pull requests.' :
      'Your change could not be saved. Check your connection and try again.';
  }

  document.addEventListener('click', (e) => {
    const tab = e.target.closest('[data-tab]');
    if (tab) { state.filter = tab.dataset.tab; try { localStorage.setItem('prdesk.filter', state.filter); } catch (err) {} render(); return; }
    const btn = e.target.closest('button[data-act]');
    if (!btn) return;
    const card = btn.closest('[data-pr]'); if (!card) return;
    const key = card.dataset.pr;
    const act = btn.dataset.act;
    if (act === 'event') { setLocal(key, { event: btn.dataset.event }); render(); saveSoon(key); }
    else if (act === 'reset') { const pr = state.prs.get(key); setLocal(key, { comment: pr.comment || '' }); render(); saveSoon(key); }
    else if (act === 'queue') { clearTimeout(timers.get(key)); save(key, { status: 'queued' }); }
    else if (act === 'hold') { clearTimeout(timers.get(key)); save(key, { status: 'hold' }); }
    else if (act === 'edit') { save(key, { status: 'draft' }); }
  });
  document.addEventListener('input', (e) => {
    const el = e.target; const card = el.closest && el.closest('[data-pr]'); if (!card) return;
    const key = card.dataset.pr;
    if (el.dataset.act === 'comment') { setLocal(key, { comment: el.value }); saveSoon(key); }
  });
  document.addEventListener('change', (e) => {
    const el = e.target; const card = el.closest && el.closest('[data-pr]'); if (!card) return;
    const key = card.dataset.pr;
    if (el.dataset.act === 'fix') {
      const ids = [...card.querySelectorAll('input[data-act="fix"]:checked')].map(i => i.dataset.fix);
      setLocal(key, { fixes: ids }); saveSoon(key);
    } else if (el.dataset.act === 'merge') { setLocal(key, { merge: el.checked }); saveSoon(key); }
  });

  render();

  (async function start() {
    const db = await window.claude?.use?.('db');
    if (!db) { $('notice').textContent = 'Open this page in Claude to see and decide on pull requests.'; return; }
    state.db = db;
    const user = await window.claude.use('user');
    if (user) { try { const c = await user.can('data.write'); if (c === false) state.canWrite = false; } catch (e) {} }

    const slow = setTimeout(() => { if (!state.loaded.prs) $('notice').textContent = "The desk can't be reached yet. It will fill in when the connection returns."; }, 10000);
    db.collection('prs').onSnapshot((snap) => {
      state.prs = new Map(snap.docs.map(d => [d.id, d.data()]));
      if (!snap.metadata.fromCache) { state.loaded.prs = true; clearTimeout(slow); }
      else if (snap.size) state.loaded.prs = true;
      const latest = [...state.prs.values()].map(p => p.reviewedAt).filter(Boolean).sort().pop();
      $('reviewed').textContent = latest ? 'last review ' + fmtTime(latest) : 'no reviews yet';
      render();
    }, () => { clearTimeout(slow); state.loaded.prs = true; $('notice').textContent = 'The desk could not load. Reopen the page to try again.'; });
    db.collection('decisions').onSnapshot((snap) => {
      state.decisions = new Map(snap.docs.map(d => [d.id, d.data()]));
      state.loaded.decisions = true;
      render();
    }, () => {});
  })();
})();
</script>

