    42	    $exceptionStatusCode = $_.Exception.StatusCode
    43	    $is404 = ($responseStatusCode -eq [System.Net.HttpStatusCode]::NotFound) -or
    44	             ($responseStatusCode -eq 'NotFound') -or
    45	             ($responseStatusCode -eq 404) -or
    46	             ($exceptionStatusCode -eq [System.Net.HttpStatusCode]::NotFound) -or
    47	             ($_.Exception.Message -match 'NotFound|404')
    48	    if ($is404) {
    49	      Write-Verbose "Group ($GroupId) was not found in the tenant and will be skipped. This may be an external partner group assigned via GDAP, or the group may have been deleted. Details: $($_.Exception.Message)"
    50	    } else {
