    57	
    58	  try {
    59	    $members = Invoke-MtGraphRequest -RelativeUri "groups/$GroupId/members" -ApiVersion v1.0
    60	
    61	    if (-not $Recursive) {
    62	      return $members
    63	    }
    64	
    65	    # Process nested groups recursively
    66	    $nestedGroups = $members | Where-Object { $_.'@odata.type' -eq "#microsoft.graph.group" }
    67	    foreach ($nestedGroup in $nestedGroups) {
    68	      if ($nestedGroup.id) {
    69	        try {
    70	          $nestedMembers = Get-MtGroupMember -GroupId $nestedGroup.id -Recursive
    71	          if ($nestedMembers) {
    72	            $members += $nestedMembers
    73	          }
    74	        } catch {
    75	          Write-Warning "Failed to get members for nested group '$($nestedGroup.id)': $($_.Exception.Message)"
    76	        }
    77	      }
    78	    }
