        @{
            Path         = $file.FullName
            RelativePath = $relativePath
            Allowed      = $relativePath -in $script:AllowedFiles
            AllowBare    = $relativePath -in $script:AllowedBareSwitchFiles
            IsCheck      = $relativePath -like 'tests/*' -or $relativePath -like 'packs/*'
        }
    }
